ROUTE_CACHE = {}

def fetch_geometry(wp):
    s = ";".join(f"{lon},{lat}" for lat, lon in wp)
    base = "http://router.project-osrm.org/route/v1/driving/"
    url = base + s + "?overview=full&geometries=geojson&continue_straight=false"
    d = json.load(urllib.request.urlopen(url, timeout=60))
    coords = d["routes"][0]["geometry"]["coordinates"]
    return [[lat, lon] for lon, lat in coords]

def get_route(rid):
    if rid in ROUTE_CACHE: return ROUTE_CACHE[rid]
    pts = BAKED.get(rid)
    if not pts: pts = fetch_geometry(LOOPS[rid]["wp"])
    path = build_path(pts)
    ROUTE_CACHE[rid] = path
    return path

def haversine(a, b):
    R = 6371000.0
    p1 = math.radians(a[0]); p2 = math.radians(b[0])
    dphi = math.radians(b[0]-a[0]); dl = math.radians(b[1]-a[1])
    x = math.sin(dphi/2)**2 + math.cos(p1)*math.cos(p2)*math.sin(dl/2)**2
    return 2*R*math.asin(math.sqrt(x))

def build_path(pts):
    cum = [0.0]
    for i in range(1, len(pts)): cum.append(cum[-1] + haversine(pts[i-1], pts[i]))
    return {"pts": pts, "cum": cum, "total": cum[-1]}

def point_at(path, dist):
    total = path["total"]
    if total <= 0: return path["pts"][0]
    dist = dist % total
    cum = path["cum"]; pts = path["pts"]
    lo = 0; hi = len(cum)-1
    while lo < hi:
        mid = (lo+hi)//2
        if cum[mid] < dist: lo = mid+1
        else: hi = mid
    i = max(1, lo)
    seg = cum[i]-cum[i-1]
    f = 0 if seg == 0 else (dist-cum[i-1])/seg
    a = pts[i-1]; b = pts[i]
    return [a[0]+(b[0]-a[0])*f, a[1]+(b[1]-a[1])*f]

def geocode(q, limit=6):
    url = "https://nominatim.openstreetmap.org/search?format=jsonv2&limit=" + str(limit) + "&q=" + urllib.parse.quote(q)
    req = urllib.request.Request(url, headers={"User-Agent": "GhostGPS/1.0 (location helper)", "Accept-Language": "ru,en"})
    data = json.load(urllib.request.urlopen(req, timeout=15))
    out = []
    for r in data:
        try: out.append({"name": r.get("display_name", ""), "lat": float(r["lat"]), "lon": float(r["lon"])})
        except (KeyError, ValueError, TypeError): continue
    return out


class Backend:
    def __init__(self):
        self.mode = "connecting"; self.error = ""; self.fast = False; self._loc = None; self._dvt = None
        self._reconnecting = False; self._fails = 0; self._next_try = 0.0
        self._start_connect()

    def _start_connect(self):
        if self._reconnecting: return
        self._reconnecting = True; self.mode = "connecting"
        threading.Thread(target=self._connect, daemon=True).start()

    def _get_rsd(self):
        from pymobiledevice3.remote.remote_service_discovery import RemoteServiceDiscoveryService
        for port in [49151, 49152]:
            try: data = json.load(urllib.request.urlopen(f"http://127.0.0.1:{port}/", timeout=3))
            except Exception: continue
            for _udid, tunnels in data.items():
                for t in tunnels:
                    addr = t.get("tunnel-address"); tport = t.get("tunnel-port")
                    if addr and tport:
                        rsd = RemoteServiceDiscoveryService((addr, int(tport))); rsd.connect(); return rsd
        return None

    def _connect(self):
        old = self._dvt; self._dvt = None; self._loc = None
        if old:
            try: old.__exit__(None, None, None)
            except Exception: pass
        try:
            try:
                from pymobiledevice3.services.dvt.dvt_secure_socket_proxy import DvtSecureSocketProxyService
                from pymobiledevice3.services.dvt.instruments.location_simulation import LocationSimulation
                provider = None
                try: provider = self._get_rsd()
                except Exception as e: self.error = f"tunneld: {e}"
                if provider is None:
                    from pymobiledevice3.lockdown import create_using_usbmux
                    provider = create_using_usbmux()
                self._dvt = DvtSecureSocketProxyService(lockdown=provider)
                self._dvt.__enter__()
                self._loc = LocationSimulation(self._dvt)
                self.mode = "api"; self.fast = True; self.error = ""; self._fails = 0
                return
            except Exception as e:
                self.error = f"api: {e}"
            try:
                subprocess.run([sys.executable, "-m", "pymobiledevice3", "version"], capture_output=True, timeout=15)
                self.mode = "cli"; self.fast = False; self._fails = 0
            except Exception as e:
                self.mode = "none"; self.error = f"cli: {e}"
        finally:
            self._reconnecting = False

    def set(self, lat, lon):
        if self.mode == "api":
            try:
                self._loc.set(lat, lon); self._fails = 0; return True
            except Exception as e:
                self.error = f"set: {e}"; self._fails += 1
                if self._fails >= 3: self._start_connect()
                return False
        if self.mode == "cli":
            try:
                subprocess.run([sys.executable, "-m", "pymobiledevice3", "developer", "dvt", "simulate-location", "set", "--", str(lat), str(lon)], capture_output=True, timeout=30)
                return True
            except Exception as e:
                self.error = f"set: {e}"; return False
        if self.mode == "none":
            now = time.time()
            if now >= self._next_try:
                self._next_try = now + 5.0; self._start_connect()
        return False

    def clear(self):
        try:
            if self.mode == "api": self._loc.clear()
            elif self.mode == "cli": subprocess.run([sys.executable, "-m", "pymobiledevice3", "developer", "dvt", "simulate-location", "clear"], capture_output=True, timeout=30)
        except Exception: pass

class Engine:
    def __init__(self, backend):
        self.b = backend; self.lock = threading.RLock()
        self.mode = "idle"; self.active = None; self.speed = 110.0
        self.dist = 0.0; self.cur = [55.7558, 37.6173]; self.path = None
        threading.Thread(target=self._loop, daemon=True).start()

    def set_point(self, lat, lon):
        with self.lock:
            self.mode = "teleport"; self.active = None; self.path = None; self.cur = [lat, lon]
        self.b.set(lat, lon)

    def start_route(self, rid, speed):
        path = get_route(rid)
        with self.lock:
            self.path = path; self.active = rid; self.speed = float(speed); self.dist = 0.0; self.mode = "route"

    def stop(self):
        with self.lock: self.mode = "idle"

    def clear(self):
        with self.lock:
            self.mode = "idle"; self.active = None; self.path = None
        self.b.clear()

    def progress(self):
        with self.lock:
            if self.mode == "route" and self.path and self.path["total"]:
                return round(100.0 * (self.dist % self.path["total"]) / self.path["total"], 1)
        return 0.0

    def _loop(self):
        last = time.time()
        while True:
            dt = max(0.05, time.time()-last); last = time.time()
            with self.lock:
                mode = self.mode; path = self.path; spd = self.speed; cur = self.cur
            if mode == "route" and path:
                self.dist += (spd/3.6)*dt
                p = point_at(path, self.dist)
                with self.lock: self.cur = p
                self.b.set(p[0], p[1])
            elif mode == "teleport" and cur:
                self.b.set(cur[0], cur[1])
            time.sleep(0.25 if self.b.fast else 1.0)

